from rdkit import Chem
from rdkit.Chem import AllChem
s1='[C]1N(c2c(C(C)C)cccc2C(C)=C)C=CN1c1c(C(C)C)cccc1C(C)C'
s2='[C]1N(c2c(C(C)C)cccc2C(C)C)C=CN1c1c(C(C)C)cccc1C(C)C'
for s in [s1,s2]:
 m=Chem.AddHs(Chem.MolFromSmiles(s));print('SMILES',Chem.MolToSmiles(m), 'atoms',m.GetNumAtoms());
 for a in m.GetAtoms():
  if a.GetSymbol()!='H':print(a.GetIdx(),a.GetSymbol(),str([n.GetIdx() for n in a.GetNeighbors()]),end='; ')
 print()
 res=AllChem.EmbedMolecule(m,randomSeed=22,maxAttempts=1000)
 print('embed',res)
 if res==0:
  print('mmff',AllChem.MMFFOptimizeMolecule(m,maxIters=1000));
  Chem.MolToMolFile(m,'top.mol' if s==s1 else 'bottom.mol')
